+    || (record.provenance === "artifact" && reference.kind === "artifact")
+    || (record.provenance === "assessment"
+      && (reference.kind === "question-check" || reference.kind === "quiz-result"))
+    || (record.provenance === "review" && reference.kind === "card-review");
+}
